import sys

def main():
    s = sys.stdin.readline().strip()
    l = r = 0
    for c in s:
        if c == '(':
            l += 1
        elif c == ')':
            if l:
                l -= 1
            else:
                r += 1
    runs = []
    for c in s:
        if runs and runs[-1][0] == c:
            runs[-1][1] += 1
        else:
            runs.append([c, 1])
    res = set()

    def dfs(idx, l, r, open_, cur):
        if idx == len(runs):
            if l == 0 and r == 0 and open_ == 0:
                res.add(cur)
            return
        c, t = runs[idx]
        if c == '(':
            for j in range(min(t, l) + 1):
                keep = t - j
                dfs(idx + 1, l - j, r, open_ + keep, cur + '(' * keep)
        elif c == ')':
            for j in range(min(t, r) + 1):
                keep = t - j
                if keep > open_:
                    continue
                dfs(idx + 1, l, r - j, open_ - keep, cur + ')' * keep)
        else:
            dfs(idx + 1, l, r, open_, cur + c * t)

    dfs(0, l, r, 0, '')
    out = sorted(res)
    print(len(out))
    for x in out:
        print(x)

main()

